import{_ as a,c as s,o,ah as i,ao as l,ap as r}from"./chunks/framework.Dq2_gudl.js";const h=JSON.parse('{"title":"Pets in Heaven — Eles, o Céu e o Seu Luto","description":"Para quem perdeu um animal de estimação: o que a Bíblia diz sobre os animais, a eternidade e o cuidado de Deus — quatro leituras acolhedoras.","frontmatter":{"title":"Pets in Heaven — Eles, o Céu e o Seu Luto","description":"Para quem perdeu um animal de estimação: o que a Bíblia diz sobre os animais, a eternidade e o cuidado de Deus — quatro leituras acolhedoras."},"headers":[],"relativePath":"pt/pets-in-heaven/index.md","filePath":"pt/pets-in-heaven/index.md"}'),t={name:"pt/pets-in-heaven/index.md"};function n(p,e,u,d,c,m){return o(),s("div",null,[...e[0]||(e[0]=[i('<div class="pl-quote"><p>“Depois que ele partiu, a única coisa que eu queria saber era: ele está bem? Vamos nos ver de novo?”</p><p class="pl-quote-soft">A Bíblia não responde tudo em uma frase — mas dá luz suficiente para enxergar esperança na noite mais escura.</p></div><section class="pl-section"><h2>Antes de começar</h2><p class="pl-lead">Este não é um lugar que pede que você “supere logo”. Estas quatro leituras são para você — que ainda sente a falta.</p><p>Perder um companheiro animal é um tipo muito particular de luto. As pessoas dizem “era só um cachorro” ou “é só pegar outro” — mas você sabe que não é verdade. Ele conhecia o som dos seus passos chegando. No seu ano mais difícil, ele ficou encostado nos seus pés. O que partiu com ele foi o primeiro olhar que te recebia toda manhã.</p><p>A Bíblia, na verdade, fala muito sobre animais. Deus os criou, os alimenta, faz uma aliança com eles e os coloca dentro do mundo que promete renovar. Esses versículos não provam que “todo animal de estimação está no céu” — a Bíblia não promete isso — mas revelam algo delicado: <strong>no plano de Deus, os animais nunca foram figurantes descartáveis.</strong></p><p>Que o que você encontrar aqui seja mais do que versículos — que seja o Deus que se lembra até de um pardal, lembrando-se do seu.</p></section><section class="pl-section"><h2>Quatro leituras para você</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/pt/pets-in-heaven/will-i-see-my-pet-again">Vou Ver Meu Pet de Novo?</a></h3><p>A esperança da Bíblia para os animais e o céu — a própria criação espera a redenção, e a nova criação ainda tem animais.</p><p class="pl-quote-soft">Romanos 8:19-22 · Isaías 11:6-9 · Apocalipse 21:4-5</p></div><div class="pl-new-card"><h3><a href="/pt/pets-in-heaven/not-one-sparrow-forgotten">Nem um Pardal É Esquecido</a></h3><p>Ele era tão pequeno — o mundo vai lembrar dele? Jesus disse que nem um pardal cai sem que o Pai saiba.</p><p class="pl-quote-soft">Mateus 10:29-31 · Salmos 147:9 · Salmos 36:6</p></div><div class="pl-new-card"><h3><a href="/pt/pets-in-heaven/rainbow-bridge-covenant">Além da Ponte do Arco-Íris</a></h3><p>“Ponte do Arco-Íris” é uma imagem bonita — e a Bíblia realmente tem um arco-íris: a aliança eterna de Deus com <em>todo ser vivente</em>.</p><p class="pl-quote-soft">Gênesis 9:9-13 · Isaías 65:25 · Apocalipse 5:13</p></div><div class="pl-new-card"><h3><a href="/pt/pets-in-heaven/permission-to-grieve">Permissão Para Sofrer</a></h3><p>Deus guarda suas lágrimas em um vaso. O luto não é falta de fé — é amor que continua.</p><p class="pl-quote-soft">Salmos 56:8 · Salmos 34:18 · Mateus 5:4</p></div></div></section><section class="pl-section"><h2>Como ler estas páginas</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>Devagar — não tudo de uma vez</h3><p>Um parágrafo já basta. Se um versículo te fizer chorar, pare ali. Isso não é fraqueza; é amor em movimento.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Coloque o nome dele no versículo</h3><p>Ao ler “Ele dá alimento aos animais”, tente dizer o nome dele nessa frase. Deus cuidou dele assim também.</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>Depois, diga uma coisa a ele</h3><p>Não precisa ser bonito. “Estou com saudade” já é suficiente. Se quiser dizer mais, o diário guiado do PetLoss fica com você.</p></div></div></section><section class="pl-section"><h2>Todos os versículos em um só lugar</h2><p class="pl-lead">Todas as passagens citadas nestas quatro leituras, reunidas aqui para reler e consultar com calma.</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/pt/pets-in-heaven/will-i-see-my-pet-again">Vou Ver Meu Pet de Novo?</a></h3><ul class="pl-verse-list"><li>Romanos 8:19-22</li><li>Isaías 11:6-9</li><li>Apocalipse 21:4-5</li><li>Salmos 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/pt/pets-in-heaven/not-one-sparrow-forgotten">Nem um Pardal É Esquecido</a></h3><ul class="pl-verse-list"><li>Mateus 10:29-31</li><li>Salmos 147:9</li><li>Salmos 36:6</li><li>Salmos 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/pt/pets-in-heaven/rainbow-bridge-covenant">Além da Ponte do Arco-Íris</a></h3><ul class="pl-verse-list"><li>Gênesis 9:9-13</li><li>Isaías 65:25</li><li>Apocalipse 5:13</li><li>Salmos 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/pt/pets-in-heaven/permission-to-grieve">Permissão Para Sofrer</a></h3><ul class="pl-verse-list"><li>Salmos 56:8</li><li>Salmos 34:18</li><li>Salmos 147:3</li><li>Mateus 5:4</li><li>João 11:35</li><li>Apocalipse 21:4</li></ul></div></div></section><div class="pl-cta"><h2>Que você seja acolhido com delicadeza aqui.</h2><p>Se você quer um lugar para guardar as fotos dele e escrever o que não teve tempo de dizer, o PetLoss fica quietinho ao seu lado — sem conta, sem uploads, totalmente offline.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Baixar na App Store</a><p class="pl-disclaimer">Estas leituras oferecem reflexão de fé e companhia emocional; não constituem aconselhamento médico, psicológico ou terapêutico. Se o luto impedir você de viver por muito tempo, procure um profissional licenciado ou uma linha de apoio local. As citações bíblicas são da King James Version (KJV).</p></div><div class="pl-bible"><h3>Deixe a Palavra de Deus continuar com você</h3><p>Todos os versículos destas quatro leituras vêm da Bíblia. Com o Rainbow Bible, você pode ler as Escrituras a qualquer momento e criar um widget de versículo diário — uma pequena luz nos dias em que sente saudade.</p><div class="pl-bible-shots"><figure><img src="'+l+'" alt="Widget do Rainbow Bible exibindo 2 Timóteo 2:13" loading="lazy"><figcaption>Versículo diário na tela inicial</figcaption></figure><figure><img src="'+r+'" alt="App Rainbow Bible — tema Pets no Céu exibindo Mateus 10:29-31" loading="lazy"><figcaption>Leia a Palavra no tema Pets no Céu</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Baixar o Rainbow Bible na App Store</a></div>',7)])])}const f=a(t,[["render",n]]);export{h as __pageData,f as default};
